/**
 * Client-side validation for hosting configuration and secret commands.
 * These checks catch stable syntax and reserved-name errors before a network
 * request. The server remains authoritative.
 */
/** `hosting.egressDomains` cap (the manifest schema and deploy body agree). */
export const MAX_EGRESS_DOMAINS = 64;
/** Max secrets per deployment. */
export const MAX_SECRETS = 32;
/** Max secret value size in bytes. */
export const MAX_SECRET_VALUE_BYTES = 4096;
/** Max secret name length. */
export const MAX_SECRET_NAME_LENGTH = 64;
/** Secret names the platform manages; user writes are rejected. */
export const RESERVED_SECRET_NAME_PREFIX = "CURSOR_";
/** Pushed container images per team, uploads in flight included. */
export const MAX_CONTAINER_IMAGES = 100;
/** Compressed `docker save` tarball cap per image. */
export const MAX_CONTAINER_IMAGE_BYTES = 8 * 1024 * 1024 * 1024;
const CONTAINER_IMAGE_NAME_PATTERN = /^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$/;
/** Returns a human error message, or undefined when the image name is valid. */
export function validateContainerImageName(name) {
    if (name.length >= 2 && CONTAINER_IMAGE_NAME_PATTERN.test(name)) {
        return undefined;
    }
    return `Invalid image name "${name}": use 2–64 lowercase letters, digits, ".", "_" or "-", starting and ending with a letter or digit.`;
}
/**
 * Additional environment names managed by Cursor. Do not include these in
 * `hosting.secretNames` or pass them to secret commands.
 */
export const PLATFORM_HOSTED_STORAGE_SECRET_NAMES = ["AGENT_SERVE_DEPLOYMENT_ID"];
const SECRET_NAME_PATTERN = /^[A-Z][A-Z0-9_]*$/;
// Lowercase hostname with >=2 labels, an alphabetic TLD, and at most one
// leading `*.` wildcard. Labels: alphanumeric with interior hyphens.
const EGRESS_DOMAIN_PATTERN = /^(\*\.)?([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]+$/;
/** `host:port` asks for raw TCP egress; a wildcard host has no address to open. */
const EGRESS_TCP_PATTERN = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]+:([1-9]\d{0,4})$/;
/** Returns a human error message, or undefined when the domain is valid. */
export function validateEgressDomain(domain) {
    if (EGRESS_DOMAIN_PATTERN.test(domain)) {
        return undefined;
    }
    const tcp = EGRESS_TCP_PATTERN.exec(domain);
    if (tcp !== null && Number(tcp[3]) <= 65535) {
        return undefined;
    }
    return `Invalid egress domain ${JSON.stringify(domain)}: use a lowercase hostname with at least two labels and an alphabetic TLD (e.g. "api.example.com"), optionally with a single leading "*." wildcard or a trailing ":port" for raw TCP.`;
}
/**
 * True when an `egressDomains` entry allows HTTPS to `hostname`: an exact
 * match, or a `*.` wildcard that matches a subdomain. A `host:port` entry
 * opens raw TCP and does not count.
 */
export function egressAllowsHost(domains, hostname) {
    const host = hostname.toLowerCase();
    return domains.some((domain) => domain.startsWith("*.") ? host.endsWith(domain.slice(1)) : domain === host);
}
/**
 * Returns a human error message, or undefined when the name is a valid
 * secret name. Grammar only — reserved names are checked separately so the
 * manifest's declarative `secretNames` can mention them with a softer
 * diagnostic than the hard write-time rejection.
 */
export function validateSecretName(name) {
    if (name.length > MAX_SECRET_NAME_LENGTH) {
        return `Secret name ${JSON.stringify(name)} is too long (max ${MAX_SECRET_NAME_LENGTH} characters).`;
    }
    if (!SECRET_NAME_PATTERN.test(name)) {
        return `Invalid secret name ${JSON.stringify(name)}: use UPPER_SNAKE_CASE starting with a letter (${SECRET_NAME_PATTERN}).`;
    }
    return undefined;
}
/**
 * True when the platform manages this name (`CURSOR_*` or hosted-storage
 * env vars); user writes / deletes are rejected.
 */
export function isReservedSecretName(name) {
    if (name.startsWith(RESERVED_SECRET_NAME_PREFIX)) {
        return true;
    }
    const upper = name.toUpperCase();
    return PLATFORM_HOSTED_STORAGE_SECRET_NAMES.some((managed) => managed === upper);
}
/**
 * Grammar and platform-managed-name errors in declared egress domains and
 * secret names, each prefixed with its field (`egressDomains: …`).
 */
export function hostingEntryErrors(declared) {
    const errors = [];
    for (const domain of declared.egressDomains ?? []) {
        const domainError = validateEgressDomain(domain);
        if (domainError !== undefined) {
            errors.push(`egressDomains: ${domainError}`);
        }
    }
    for (const name of declared.secretNames ?? []) {
        const nameError = validateSecretName(name);
        if (nameError !== undefined) {
            errors.push(`secretNames: ${nameError}`);
        }
        else if (isReservedSecretName(name)) {
            errors.push(`secretNames: ${JSON.stringify(name)} is platform-managed (CURSOR_* / reserved hosted-storage names); omit it from secretNames.`);
        }
    }
    return errors;
}
/**
 * Human error for a secret name a user is trying to write or delete:
 * grammar plus platform-managed names (`CURSOR_*`, hosted storage).
 */
export function validateSettableSecretName(name) {
    const nameError = validateSecretName(name);
    if (nameError !== undefined) {
        return nameError;
    }
    if (isReservedSecretName(name)) {
        return `Secret name ${JSON.stringify(name)} is platform-managed; user secrets cannot claim CURSOR_* or reserved hosted-storage names.`;
    }
    return undefined;
}
const CURSOR_EVENT_REPO_PATTERNS = [
    /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/,
    /^gitlab\.com\/[a-z0-9_.-]+(?:\/[a-z0-9_.-]+){1,9}$/i,
    /^bitbucket\.org\/[a-z0-9_-]+\/[a-z0-9_.-]+$/i,
];
/** `owner/name`, `gitlab.com/<group>/…/<project>`, or `bitbucket.org/<workspace>/<repo>`. Mirrors the backend's deploy repository grammar. */
export function isValidCursorEventRepo(repo) {
    return CURSOR_EVENT_REPO_PATTERNS.some((pattern) => pattern.test(repo)) && !repo.includes("..");
}
